import{_ as s,H as e,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"34 | 搭建一个分布式实验环境：纸上得来终觉浅，绝知此事要躬行","description":"","frontmatter":{},"headers":[{"level":2,"title":"搭建目标","slug":"搭建目标","link":"#搭建目标","children":[]},{"level":2,"title":"搭建前的准备","slug":"搭建前的准备","link":"#搭建前的准备","children":[]},{"level":2,"title":"Kubernetes集群搭建","slug":"kubernetes集群搭建","link":"#kubernetes集群搭建","children":[{"level":3,"title":"1. 安装Docker","slug":"_1-安装docker","link":"#_1-安装docker","children":[]},{"level":3,"title":"2. 安装部署kubeadm、kubelet、kubectl","slug":"_2-安装部署kubeadm、kubelet、kubectl","link":"#_2-安装部署kubeadm、kubelet、kubectl","children":[]},{"level":3,"title":"3. 部署Master节点","slug":"_3-部署master节点","link":"#_3-部署master节点","children":[]},{"level":3,"title":"4. 部署Worker节点","slug":"_4-部署worker节点","link":"#_4-部署worker节点","children":[]},{"level":3,"title":"5. 安装网络插件","slug":"_5-安装网络插件","link":"#_5-安装网络插件","children":[]},{"level":3,"title":"6. 验证","slug":"_6-验证","link":"#_6-验证","children":[]},{"level":3,"title":"7. 可能遇到的问题","slug":"_7-可能遇到的问题","link":"#_7-可能遇到的问题","children":[]}]},{"level":2,"title":"Nginx服务部署","slug":"nginx服务部署","link":"#nginx服务部署","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"分布式技术原理与算法解析/34-搭建一个分布式实验环境：纸上得来终觉浅，绝知此事要躬行.md","filePath":"分布式技术原理与算法解析/34-搭建一个分布式实验环境：纸上得来终觉浅，绝知此事要躬行.md","lastUpdated":1779818952000}'),t={name:"分布式技术原理与算法解析/34-搭建一个分布式实验环境：纸上得来终觉浅，绝知此事要躬行.md"};function l(i,a,c,o,r,d){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="_34-搭建一个分布式实验环境-纸上得来终觉浅-绝知此事要躬行" tabindex="-1">34 | 搭建一个分布式实验环境：纸上得来终觉浅，绝知此事要躬行 <a class="header-anchor" href="#_34-搭建一个分布式实验环境-纸上得来终觉浅-绝知此事要躬行" aria-label="Permalink to &quot;34 | 搭建一个分布式实验环境：纸上得来终觉浅，绝知此事要躬行&quot;">​</a></h1><p>你好，我是聂鹏程。</p><p>上一讲，我以购买火车票为例，为你串讲了分布式技术的应用，帮助你理解所学分布式技术可以应用到哪些业务中。其实，到目前为止，我们主要是从理论上学习相关的分布式技术。但，“纸上得来终觉浅，绝知此事要躬行”。</p><p>今天，我就以Kubernetes为例，和你一起搭建一个分布式实验环境。我先简单和你说下这篇文章的内容分配：</p><ul><li>不会特别详细地讲述搭建过程，而是着重说明搭建的主要步骤以及可能遇到的问题；</li><li>在讲述搭建过程时，串联一下其中涉及的分布式相关知识；</li><li>搭建完Kubernetes集群之后，我会以部署Nginx服务为例，帮助你更直观地体验分布式技术，以巩固、加深对分布式技术的理解。</li></ul><p>话不多说，接下来，我们就一起搭建这个分布式实验环境吧。</p><h2 id="搭建目标" tabindex="-1">搭建目标 <a class="header-anchor" href="#搭建目标" aria-label="Permalink to &quot;搭建目标&quot;">​</a></h2><p>Kubernetes是Google开源的容器集群管理系统，是Borg的开源版本。我在 <a href="https://time.geekbang.org/column/article/148187" target="_blank" rel="noreferrer">第9篇文章</a> 中讲解集中式架构时，和你分析过Kubernetes集群属于主从架构的分布式集群。</p><p>Kubernetes集群主要由Master节点和Worker节点组成。Master节点就是中心服务器，负责对集群进行调度管理；Worker节点是真正的工作节点，负责运行业务应用的容器。而容器是一种虚拟化技术，通过限制自身使用的资源来实现资源隔离，可以为应用提供一整套运行环境，从而实现了服务运行环境的隔离，进而实现了故障隔离。你可以回顾下 <a href="https://time.geekbang.org/column/article/175213" target="_blank" rel="noreferrer">第30篇文章</a> 中，资源隔离的相关内容。</p><p>接下来，我们明确下这次搭建分布式实验室环境的目标：</p><ul><li>搭建一个Kubernetes集群，包括一个Master节点，两个Worker节点;</li><li>在Kubernetes集群上创建一个Nginx服务。</li></ul><h2 id="搭建前的准备" tabindex="-1">搭建前的准备 <a class="header-anchor" href="#搭建前的准备" aria-label="Permalink to &quot;搭建前的准备&quot;">​</a></h2><p>今天我们要搭建的Kubernetes集群，以3台服务器为例，一台作为Master节点，两台作为Worker节点。服务器应具备的条件如下：</p><ul><li>Ubuntu 16.04操作系统；</li><li>2GB或以上的内存；</li><li>2核CPU或以上；</li><li>服务器间网络连通；</li><li>每台服务器具有唯一的主机名、MAC地址和product_uuid；</li><li>通过执行命令swapoff -a来关闭Swap；</li><li>30GB及以上的磁盘空间；</li><li>具备外网访问权限，以方便获取相关镜像。</li></ul><p>在这次部署中，我采用的机器配置如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%8A%80%E6%9C%AF%E5%8E%9F%E7%90%86%E4%B8%8E%E7%AE%97%E6%B3%95%E8%A7%A3%E6%9E%90/images/178383/a96f67cb7fc7df583f73c098d377f55e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E6%8A%80%E6%9C%AF%E5%8E%9F%E7%90%86%E4%B8%8E%E7%AE%97%E6%B3%95%E8%A7%A3%E6%9E%90/images/178383/a96f67cb7fc7df583f73c098d377f55e.jpg" alt=""></a></p><p>准备工作完成后，我们就开始搭建集群吧。</p><h2 id="kubernetes集群搭建" tabindex="-1">Kubernetes集群搭建 <a class="header-anchor" href="#kubernetes集群搭建" aria-label="Permalink to &quot;Kubernetes集群搭建&quot;">​</a></h2><p>搭建Kubernetes集群的步骤，主要包括安装Docker，安装部署kubeadm、kubelet、kubectl，部署Master节点，部署Worker节点，安装网络插件这几步。</p><p>其中，安装Docker、部署Master节点和Worker节点涉及分布式的，需要在多个节点上部署，比如Docker节点需要在每个Worker节点部署，Master节点若为集群模式，需要在多个节点上配置主备，Worker节点需要与Master节点建立连接等。</p><p>接下来， 我们具体看看如何一步一步搭建出Kubernetes集群吧。</p><h3 id="_1-安装docker" tabindex="-1">1. 安装Docker <a class="header-anchor" href="#_1-安装docker" aria-label="Permalink to &quot;1\\. 安装Docker&quot;">​</a></h3><p>Kubernetes是一个容器集群管理系统，因此每个Worker节点会运行容器，以实现业务运行环境隔离。我们在每台服务器上采用如下命令安装Docker：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt-get install -y docker.io</span></span></code></pre></div><h3 id="_2-安装部署kubeadm、kubelet、kubectl" tabindex="-1">2. 安装部署kubeadm、kubelet、kubectl <a class="header-anchor" href="#_2-安装部署kubeadm、kubelet、kubectl" aria-label="Permalink to &quot;2\\. 安装部署kubeadm、kubelet、kubectl&quot;">​</a></h3><p>kubeadm是Kubernetes社区提供的一个部署工具，该工具将kubelet组件之外的其他组件均采用容器部署，实现了自动化， 避免了手动部署容器的麻烦，简化了部署操作。</p><p>其中，Master节点包括API Server、Scheduler、Cluster State Store(默认etcd)和Control Manager Srever核心组件；Worker节点包括kubelet和kube-proxy核心组件。具体的组件功能和原理，你可以再回顾下 <a href="https://time.geekbang.org/column/article/148187" target="_blank" rel="noreferrer">第9篇文章</a> 中的相关内容。</p><p>kubelet组件本身是一个管控容器的组件，需要执行配置容器网络等操作，这些操作需要在宿主机上执行，不采用容器部署。因此，kubelet组件需要单独部署，而不能用kubeadm进行部署。</p><p>除此之外，我们还需要安装一下kubectl组件。这个组件是Kubernetes的命令行工具，通过kubectl可以部署和管理应用，查看资源，创建、删除和更新组件。</p><p>那么，如何部署kubeadm、kubelet和kubectl这三个组件呢？</p><p>apt是Linux下常用的安装管理工具，这里我就采用apt来安装这三个组件。</p><p>首先，我们需要添加Kubernetes源。</p><ul><li>你可以通过执行以下语句获取Kubernetes源（需要外网权限）：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt-get install -y apt-transport-https curl</span></span>
<span class="line"><span>curl -s https://packages.cloud.google.com/apt/doc/apt-key.gpg | sudo apt-key add -</span></span>
<span class="line"><span>cat &amp;lt;&amp;lt;EOF | sudo tee /etc/apt/sources.list.d/kubernetes.list</span></span>
<span class="line"><span>deb https://apt.kubernetes.io/ kubernetes-xenial main</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>然后使用以下命令更新源：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get update</span></span></code></pre></div><ul><li>这时，我们就可以使用如下命令来安装kubelet、kubectl和kubeadm了：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install -y kubelet kubeadm kubectl</span></span></code></pre></div><ul><li>如果没有外网访问权限，在添加kubernetes源的时候可以执行以下命令来添加阿里云的Kubernetes源：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat &amp;lt;&amp;lt;EOF | sudo tee /etc/apt/sources.list.d/kubernetes.list</span></span>
<span class="line"><span>deb https://mirrors.aliyun.com/kubernetes/apt kubernetes-xenial main</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>同样的，使用以下命令来更新源：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt-get update # 忽略gpg的报错信息</span></span></code></pre></div><p>最后，使用如下命令安装kubelet、kubectl和kubeadm：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt-get install -y kubelet kubeadm kubectl --allow-unauthenticated</span></span></code></pre></div><p>安装好这三个组件之后，我们就可以使用kubeadm来一键部署集群节点了。</p><p>首先，我们来部署Master节点。</p><h3 id="_3-部署master节点" tabindex="-1">3. 部署Master节点 <a class="header-anchor" href="#_3-部署master节点" aria-label="Permalink to &quot;3\\. 部署Master节点&quot;">​</a></h3><p>这一步其实就是容器化启动Master节点中的各个组件，直接使用kubeadm工具提供的一条命令kubeadm init即可自动安装。</p><p>kubeadm init这条命令底层其实就是将Master的各个组件，比如API Server、etcd等，以Pod形式（容器集合）运行起来。</p><p>当然了，你可以部署多个Master节点来实现集群的高可用，比如两个Master节点互为主备（你可以回顾下 <a href="https://time.geekbang.org/column/article/175545" target="_blank" rel="noreferrer">第31篇文章</a> 中介绍的主备机制）。具体的部署方法，你可以参考 <a href="https://kubernetes.io/docs/setup/production-environment/tools/kubeadm/high-availability/" target="_blank" rel="noreferrer">这篇文章</a>。</p><p>除此之外，etcd组件也可以采用集群方式部署，从而保证了数据不会丢失。etcd采用的是Raft强一致性协议，相关技术你可以再回顾下 <a href="https://time.geekbang.org/column/article/143329" target="_blank" rel="noreferrer">第4篇文章</a> 中的相关问题。</p><p><strong>在本次部署中我以一个Master节点为例为你讲解集群的搭建</strong>，关于Master为集群的方式，各节点上kubernetes配置类似，你可以参考Kubernetes官网。</p><p>在这里，我把192.168.124.49这台机器作为Master节点。在该机器上直接执行kubeadm init，即可完成部署：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm init</span></span></code></pre></div><p>如果有外网访问权限，基本就可以部署成功了。那么，我们可以根据如下信息判断自己是否部署成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your Kubernetes control-plane has initialized successfully!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To start using your cluster, you need to run the following as a regular user:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  mkdir -p $HOME/.kube</span></span>
<span class="line"><span>  sudo cp -i /etc/kubernetes/admin.conf $HOME/.kube/config</span></span>
<span class="line"><span>  sudo chown $(id -u):$(id -g) $HOME/.kube/config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You should now deploy a pod network to the cluster.</span></span>
<span class="line"><span>Run &quot;kubectl apply -f [podnetwork].yaml&quot; with one of the options listed at:</span></span>
<span class="line"><span>  https://kubernetes.io/docs/concepts/cluster-administration/addons/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then you can join any number of worker nodes by running the following on each as root:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kubeadm join 192.168.124.49:6443 --token uv17vd.q3ber8i5knxg4h0x \\</span></span>
<span class="line"><span>    --discovery-token-ca-cert-hash sha256:c55bd70d346d809e1079565cc1fc1a05f001671cc9f2d02c55bbbc4a00bcc2a3</span></span></code></pre></div><p>可以看到，想要使用集群，需要执行以下命令，执行结束后才可以使用kubectl。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p $HOME/.kube</span></span>
<span class="line"><span>cp -i /etc/kubernetes/admin.conf $HOME/.kube/config</span></span>
<span class="line"><span>chown $(id -u):$(id -g) $HOME/.kube/config</span></span></code></pre></div><p>如果没有外网访问权限，会报pull image xxxxxx的错误。</p><p>此时不要慌，从报错信息中，我们可以看到哪些镜像拉取不成功。我们可以手动在Docker Hub上寻找相对应的组件及版本，进行拉取，然后再通过Docker打tag，修改为需要的镜像。</p><p>比如，以[ERROR ImagePull]: failed to pull image k8s.gcr.io/kube-apiserver:v1.16.3为例，可以通过以下代码进行拉取。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 可以拉取的相对应的组件和版本</span></span>
<span class="line"><span>docker pull aiotceo/kube-apiserver:v1.16.3</span></span>
<span class="line"><span># 通过打tag的方式修改为所需要的镜像</span></span>
<span class="line"><span>docker tag aiotceo/kube-apiserver:v1.16.3 k8s.gcr.io/kube-apiserver:v1.16.3</span></span></code></pre></div><p>然后重新执行 kubeadm init即可。</p><p>从以上操作也可以看出， <strong>kubeadm的底层其实就是将容器化组件的操作实现了自动化， 省去了手动部署的麻烦</strong>。</p><p>部署完Master节点后，我们来继续部署Worker节点。</p><h3 id="_4-部署worker节点" tabindex="-1">4. 部署Worker节点 <a class="header-anchor" href="#_4-部署worker节点" aria-label="Permalink to &quot;4\\. 部署Worker节点&quot;">​</a></h3><p>部署Worker节点与部署Master节点类似，都可以通过命令一键部署。这里，我们使用kubeadm提供的kubeadm join命令来进行自动化部署。</p><p>kubeadm join命令的底层与kubeadm init类似，会自动以Pod形式运行Worker节点中需要的组件。不同的是，命令执行后，底层还需要将Worker节点加入到Kubernetes集群中。</p><p>执行kubeadm join命令后（具体命令如下所示），就可以看到Kubernetes集群中的节点信息了。这条命令中需要配置Master节点的IP和Port信息，目的是Worker节点根据IP和Port信息建立连接，并在建立连接的基础上，建立心跳机制。</p><p>具体的心跳机制，你可以参考 <a href="https://time.geekbang.org/column/article/175545" target="_blank" rel="noreferrer">第31篇文章</a> 中关于故障恢复的内容。</p><p>到目前为止，Kubernetes的集群已经完成大半了，下面我们继续部署集群。</p><p>根据Master节点部署成功后输出结果的最后几行可以知道，想要加入集群，可以执行kubeadm join命令。我在另外2台机器上都执行了如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm join 192.168.124.49:6443 --token uv17vd.q3ber8i5knxg4h0x \\</span></span>
<span class="line"><span>    --discovery-token-ca-cert-hash sha256:c55bd70d346d809e1079565cc1fc1a05f001671cc9f2d02c55bbbc4a00bcc2a3</span></span></code></pre></div><p>这条命令执行后，一个集中式架构的雏形就搭建完成了。接下来，我们需要安装相应的网络插件，以实现Kubernetes集群中Pod之间的通信。</p><h3 id="_5-安装网络插件" tabindex="-1">5. 安装网络插件 <a class="header-anchor" href="#_5-安装网络插件" aria-label="Permalink to &quot;5\\. 安装网络插件&quot;">​</a></h3><p>网络插件有很多，比如Canal、Flannel、Weave等。不同的插件命令不一致，具体命令可参考官网。</p><p>这里，我以安装Weave插件为例，通过执行以下命令完成安装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sysctl net.bridge.bridge-nf-call-iptables=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kubectl apply -f &quot;https://cloud.weave.works/k8s/net?k8s-version=$(kubectl version | base64 | tr -d &#39;\\n&#39;)&quot;</span></span></code></pre></div><h3 id="_6-验证" tabindex="-1">6. 验证 <a class="header-anchor" href="#_6-验证" aria-label="Permalink to &quot;6\\. 验证&quot;">​</a></h3><p>到这里，集群就部署完成了，是不是很简单呢？接下来，我就通过获取节点和Pod信息来验证一下集群部署是否成功。</p><p>可以通过刚刚安装的kubectl组件提供的命令查看集群的相关信息。比如，查看节点的运行状态可以通过kubectl get nodes来获得，查看各个组件对应的Pod运行状态可以通过kubectl get pods来获得。命令执行结果，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get nodes</span></span>
<span class="line"><span></span></span>
<span class="line"><span># NAME           STATUS   ROLES    AGE   VERSION</span></span>
<span class="line"><span># vm1-pc   Ready    master   11h   v1.16.3</span></span>
<span class="line"><span># vm2-pc   Ready    &amp;lt;none&amp;gt;   11h   v1.16.3</span></span>
<span class="line"><span># vm3-pc   Ready    &amp;lt;none&amp;gt;   24m   v1.16.3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kubectl get pods --all-namespaces</span></span>
<span class="line"><span></span></span>
<span class="line"><span># NAMESPACE     NAME                                   READY   STATUS    RESTARTS   AGE</span></span>
<span class="line"><span># kube-system   coredns-5644d7b6d9-9dprc               1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   coredns-5644d7b6d9-ljv5w               1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   etcd-vm1-pc                      1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   kube-apiserver-vm1-pc            1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   kube-controller-manager-vm1-pc   1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   kube-proxy-qpvtb                       1/1     Running   0          25m</span></span>
<span class="line"><span># kube-system   kube-proxy-v2xnb                       1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   kube-proxy-wkxzg                       1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   kube-scheduler-vm1-pc            1/1     Running   0          11h</span></span>
<span class="line"><span># kube-system   weave-net-6nj4c                        2/2     Running   0          25m</span></span>
<span class="line"><span># kube-system   weave-net-lm6dh                        2/2     Running   0          37m</span></span>
<span class="line"><span># kube-system   weave-net-vwnc2                        2/2     Running   0          37m</span></span></code></pre></div><p>可以看到，节点全部是Ready状态，各个组件对应的Pod也处于Running状态，表明部署成功。</p><h3 id="_7-可能遇到的问题" tabindex="-1">7. 可能遇到的问题 <a class="header-anchor" href="#_7-可能遇到的问题" aria-label="Permalink to &quot;7\\. 可能遇到的问题&quot;">​</a></h3><p>如果整个安装失败的话，可以重置，重新安装，即重新kubeadm init</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubeadm reset</span></span></code></pre></div><p>部署Worker节点时，pod部署不成功。原因可能是因为没有外网访问权限，镜像拉取不下来，可以通过以下命令查看pod的相关信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 检查所有pod是否正常</span></span>
<span class="line"><span>kubectl get pod --all-namespaces -o wide</span></span>
<span class="line"><span>#如果pod处于非running状态，则查看该pod：</span></span>
<span class="line"><span>kubectl describe pod xxxxx -n kube-system</span></span></code></pre></div><p>从错误信息里可以查看到是哪个镜像拉取不下来，与部署Master节点时采用的方式一样，到Docker Hub上手动拉取镜像，并设置Tag即可。</p><p>至此，Kubernetes集群就配置成功了。</p><p>集群环境搭建后，如何验证集群是可用的呢？或者说，如何在集群上运行服务呢？接下来，我就以Nginx服务为例，带你了解如何在Kubernetes集群上进行服务部署。当然，你可以参考这个例子，在Kubernetes集群上部署其他服务。</p><h2 id="nginx服务部署" tabindex="-1">Nginx服务部署 <a class="header-anchor" href="#nginx服务部署" aria-label="Permalink to &quot;Nginx服务部署&quot;">​</a></h2><p>Kubernetes推荐使用YAML配置文件的方式来创建服务，所以我接下来会使用这种方式部署完成Nginx服务的部署。</p><p>部署Nginx服务这个Demo时，我会创建两个Kubernetes对象（Kubernetes对象是Kubernetes系统中的持久实体，用于表示集群的状态），一个是Deployment，一个是Service：</p><ul><li>Deployment对象规定Pod创建的相关信息，比如期望创建几个Pod，每个Pod应该部署什么应用等。</li><li>Service对象用来给用户访问提供接口。它可以通过Label Selector（标签选择器）来指定可以访问的Pod有哪些。关于Kubernetes对象的相关内容，你可以参考 <a href="http://docs.kubernetes.org.cn/232.html" target="_blank" rel="noreferrer">这篇文章</a>。</li></ul><p>因为Pod是Kubernetes中最小的工作单元，所以Nginx服务都部署在Pod中。下面，我就来创建一个Deployment对象来创建我们期望的Pod状态。</p><p>首先，创建一个YAML配置文件，我将其命名为nginx-deployment.yaml。为将用户请求负载均衡到不同的Pod，减轻单个Pod的访问压力，这里我会创建三个Pod共同运行Nginx服务。</p><p>文件内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: nginx-deployment</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    app: nginx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  replicas: 3</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    matchLabels:</span></span>
<span class="line"><span>      app: nginx</span></span>
<span class="line"><span>  template:</span></span>
<span class="line"><span>    metadata:</span></span>
<span class="line"><span>      labels:</span></span>
<span class="line"><span>        app: nginx</span></span>
<span class="line"><span>    spec:</span></span>
<span class="line"><span>      containers:</span></span>
<span class="line"><span>      - name: nginx</span></span>
<span class="line"><span>        image: nginx:latest</span></span>
<span class="line"><span>        ports:</span></span>
<span class="line"><span>        - containerPort: 80</span></span></code></pre></div><p>文件中，replicas字段就是副本数量，也就是Pod数量，设置为3，即创建三个Pod来运行Nginx服务；template字段规定了单个Pod中运行哪些容器，这里运行的是名称为nginx的容器。</p><ul><li>创建完配置文件后，通过以下命令就可以将Deployment对象创建成功。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl apply -f nginx-deployment.yaml</span></span></code></pre></div><p>执行后，就等待对象的创建，可以通过以下命令来查看创建是否成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get deployment</span></span></code></pre></div><p>以下是我创建成功后的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NAME               READY   UP-TO-DATE   AVAILABLE   AGE</span></span>
<span class="line"><span>nginx-deployment   3/3     3            3           3m17s</span></span></code></pre></div><p>同时，你也可以通过以下命令来查看创建的Pod的信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get pod</span></span></code></pre></div><p>以下是我的输出结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NAME                               READY   STATUS    RESTARTS   AGE</span></span>
<span class="line"><span>nginx-deployment-59c9f8dff-dtg4w   1/1     Running   0          3m15s</span></span>
<span class="line"><span>nginx-deployment-59c9f8dff-f2hmv   1/1     Running   0          3m15s</span></span>
<span class="line"><span>nginx-deployment-59c9f8dff-lsvdh   1/1     Running   0          3m15s</span></span></code></pre></div><p>创建完deployment之后，我们来创建Service服务。同样是通过配置文件来创建，文件名是nginx-service.yaml，内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Service</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: nginx-service</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    app: nginx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  - port: 88</span></span>
<span class="line"><span>    targetPort: 80</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    app: nginx</span></span>
<span class="line"><span>  type: NodePort</span></span></code></pre></div><p>文件中port属性就是service对外提供的端口。</p><p>同样的，采用kubectl apply命令创建Nginx服务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl apply -f nginx-service.yaml</span></span></code></pre></div><p>执行完成后，可以通过以下命令来查看创建是否成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kubectl get service</span></span></code></pre></div><p>以下是我的输出结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NAME            TYPE        CLUSTER-IP       EXTERNAL-IP   PORT(S)          AGE</span></span>
<span class="line"><span>kubernetes      ClusterIP   10.96.0.1        &amp;lt;none&amp;gt;        443/TCP          12h</span></span>
<span class="line"><span>nginx-service   NodePort    10.101.29.9      &amp;lt;none&amp;gt;        88:30755/TCP     5m12s</span></span></code></pre></div><p>现在我们就可以通过访问Nginx服务来查看它是否部署成功了。访问该服务可以通过以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl 10.101.29.9:88</span></span></code></pre></div><p>结果如下，表明Nginx服务部署成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;!DOCTYPE html&amp;gt;</span></span>
<span class="line"><span>&amp;lt;html&amp;gt;</span></span>
<span class="line"><span>&amp;lt;head&amp;gt;</span></span>
<span class="line"><span>&amp;lt;title&amp;gt;Welcome to nginx!&amp;lt;/title&amp;gt;</span></span>
<span class="line"><span>&amp;lt;style&amp;gt;</span></span>
<span class="line"><span>    body {</span></span>
<span class="line"><span>        width: 35em;</span></span>
<span class="line"><span>        margin: 0 auto;</span></span>
<span class="line"><span>        font-family: Tahoma, Verdana, Arial, sans-serif;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>&amp;lt;/style&amp;gt;</span></span>
<span class="line"><span>&amp;lt;/head&amp;gt;</span></span>
<span class="line"><span>&amp;lt;body&amp;gt;</span></span>
<span class="line"><span>&amp;lt;h1&amp;gt;Welcome to nginx!&amp;lt;/h1&amp;gt;</span></span>
<span class="line"><span>&amp;lt;p&amp;gt;If you see this page, the nginx web server is successfully installed and</span></span>
<span class="line"><span>working. Further configuration is required.&amp;lt;/p&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&amp;lt;p&amp;gt;For online documentation and support please refer to</span></span>
<span class="line"><span>&amp;lt;a href=&quot;http://nginx.org/&quot;&amp;gt;nginx.org&amp;lt;/a&amp;gt;.&amp;lt;br/&amp;gt;</span></span>
<span class="line"><span>Commercial support is available at</span></span>
<span class="line"><span>&amp;lt;a href=&quot;http://nginx.com/&quot;&amp;gt;nginx.com&amp;lt;/a&amp;gt;.&amp;lt;/p&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&amp;lt;p&amp;gt;&amp;lt;em&amp;gt;Thank you for using nginx.&amp;lt;/em&amp;gt;&amp;lt;/p&amp;gt;</span></span>
<span class="line"><span>&amp;lt;/body&amp;gt;</span></span>
<span class="line"><span>&amp;lt;/html&amp;gt;</span></span></code></pre></div><p>在这个过程中，有两个步骤涉及 <a href="https://time.geekbang.org/column/article/173398" target="_blank" rel="noreferrer">负载均衡</a> 的相关知识：</p><ul><li>一个是创建Deployment时，该Deployment会创建三个Pod，而Pod需要部署到某个Worker节点中，因此会将Pod均衡部署到各个Worker节点中；</li><li>另一个是用户访问，Nginx服务后台三个运行的Pod都可以提供服务，用户访问到来时，可以均衡分布到各个Pod中进行处理。</li></ul><p>到这里，我们搭建的目标就完成了，下面为你留几个实验题，你可以尝试去搭建一下或运行一下，以进一步加深对分布式技术的理解。</p><ul><li>实验一：搭建高可用Kubernetes集群，也就是通过etcd实现Master节点以集群模式部署。具体搭建方法可参考 <a href="https://kubernetes.io/docs/setup/production-environment/tools/kubeadm/high-availability/" target="_blank" rel="noreferrer">https://kubernetes.io/docs/setup/production-environment/tools/kubeadm/high-availability/</a>；</li><li>实验二：在Kubernetes上部署Cassandra，其中Cassandra作为服务部署到容器中，以学习Cassandra集群的节点发现、集群组件等原理，具体搭建方法可参考 <a href="https://kubernetes.io/docs/tutorials/stateful-application/cassandra/" target="_blank" rel="noreferrer">https://kubernetes.io/docs/tutorials/stateful-application/cassandra/</a>；</li><li>实验三：在Kubernetes集群上通过部署一个MySQL服务，体验在Kubernetes集群上如何运行一个单实例有状态应用。具体搭建方法可参考 <a href="https://kubernetes.io/docs/tasks/run-application/run-single-instance-stateful-application/" target="_blank" rel="noreferrer">https://kubernetes.io/docs/tasks/run-application/run-single-instance-stateful-application/</a>。</li></ul><p>好了，整个搭建环境，我就讲到这里。</p><p>其实，到这里，对分布式世界的探索可以说才刚开始，只有动手去实践，你学到的知识才能真正转化为你自己的。加油，赶紧行动起来吧。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天，我主要带你学习了搭建分布式实验环境。</p><p>首先，我以Kubernetes为例，介绍了如何搭建 Kubernetes集群环境，其中包括容器、Master节点、Worker节点等配置和安装。</p><p>然后，在搭建好的Kubernetes集群的基础上，我以Nginx服务为例，展示了如何在Kubernetes集群上部署服务。</p><p>其实，今天我演示的Demo只是冰山一角。在Kubernetes中，有很多非常实用的功能，比如Kubernetes可以让服务持续不断运行，当有Pod出现故障时，会自动重启另一个Pod来达到Deployment配置文件中规定的期望状态；还可以自动实现版本更迭等。</p><p>相信通过本讲的学习，你会对分布式技术有更进一步的认知。加油，赶紧行动起来，为你的服务搭建一个分布式实验环境吧。</p><p>我是聂鹏程，感谢你的收听，欢迎你在评论区给我留言分享你的观点，也欢迎你把这篇文章分享给更多的朋友一起阅读。我们下期再会！</p>`,136)])])}const g=s(t,[["render",l]]);export{b as __pageData,g as default};
